insert into public.unsa_actus (title, content, tag, region, demo, created_at) values
($t$Égalité professionnelle : des avancées en Auvergne-Rhône-Alpes$t$, $t$La commission égalité, où siègent vos élus UNSA, a obtenu un budget dédié au rattrapage des écarts de rémunération et l'ouverture de postes techniques aux candidatures féminines à Lyon. Un suivi sera présenté chaque semestre.$t$, $t$Égalité H/F$t$, $t$Auvergne-Rhône-Alpes$t$, true, '2026-09-14T02:00:00+01:00'),
($t$Astreintes : l'UNSA obtient une revalorisation en Auvergne-Rhône-Alpes$t$, $t$Après plusieurs mois de négociation, la délégation UNSA Énergies Auvergne-Rhône-Alpes a obtenu une revalorisation des indemnités d'astreinte et une meilleure prise en compte des temps de trajet pour les interventions de nuit. Le détail de l'accord est disponible dans l'espace adhérent.$t$, $t$Négociation$t$, $t$Auvergne-Rhône-Alpes$t$, true, '2026-10-30T05:00:00+01:00'),
($t$Égalité professionnelle : des avancées en Bourgogne-Franche-Comté$t$, $t$La commission égalité, où siègent vos élus UNSA, a obtenu un budget dédié au rattrapage des écarts de rémunération et l'ouverture de postes techniques aux candidatures féminines à Dijon. Un suivi sera présenté chaque semestre.$t$, $t$Égalité H/F$t$, $t$Bourgogne-Franche-Comté$t$, true, '2026-10-26T06:00:00+01:00'),
($t$Réunion d'information retraite à Besançon$t$, $t$Calcul de pension, rachat de trimestres, cumul emploi-retraite : l'UNSA Énergies Bourgogne-Franche-Comté organise une réunion d'information ouverte à tous à Besançon. Un conseiller répondra à vos questions individuelles à l'issue de la présentation. Inscription conseillée via « Nous contacter ».$t$, $t$Retraite$t$, $t$Bourgogne-Franche-Comté$t$, true, '2026-09-16T07:00:00+01:00'),
($t$Égalité professionnelle : des avancées en Bretagne$t$, $t$La commission égalité, où siègent vos élus UNSA, a obtenu un budget dédié au rattrapage des écarts de rémunération et l'ouverture de postes techniques aux candidatures féminines à Rennes. Un suivi sera présenté chaque semestre.$t$, $t$Égalité H/F$t$, $t$Bretagne$t$, true, '2026-10-27T09:00:00+01:00'),
($t$Permanence syndicale à Brest$t$, $t$Vos représentants UNSA Énergies Bretagne tiennent une permanence chaque premier mardi du mois, de 11h30 à 14h, sur le site de Brest. Venez échanger sur vos droits, votre parcours professionnel ou toute difficulté rencontrée au travail. Sans rendez-vous et en toute confidentialité.$t$, $t$Permanence$t$, $t$Bretagne$t$, true, '2026-09-11T01:00:00+01:00'),
($t$Astreintes : l'UNSA obtient une revalorisation en Centre-Val de Loire$t$, $t$Après plusieurs mois de négociation, la délégation UNSA Énergies Centre-Val de Loire a obtenu une revalorisation des indemnités d'astreinte et une meilleure prise en compte des temps de trajet pour les interventions de nuit. Le détail de l'accord est disponible dans l'espace adhérent.$t$, $t$Négociation$t$, $t$Centre-Val de Loire$t$, true, '2026-10-13T06:00:00+01:00'),
($t$Télétravail : point d'étape en Centre-Val de Loire$t$, $t$Un an après la signature de l'accord télétravail, l'UNSA Énergies Centre-Val de Loire dresse le bilan : demandes acceptées, refus contestés, équipements fournis. Si votre demande a été refusée sans motif clair, contactez vos représentants : nous vous accompagnons.$t$, $t$Télétravail$t$, $t$Centre-Val de Loire$t$, true, '2026-10-23T09:00:00+01:00'),
($t$Télétravail : point d'étape en Corse$t$, $t$Un an après la signature de l'accord télétravail, l'UNSA Énergies Corse dresse le bilan : demandes acceptées, refus contestés, équipements fournis. Si votre demande a été refusée sans motif clair, contactez vos représentants : nous vous accompagnons.$t$, $t$Télétravail$t$, $t$Corse$t$, true, '2026-09-23T07:00:00+01:00'),
($t$Élections professionnelles : la liste UNSA Corse se construit$t$, $t$Vous souhaitez vous engager pour vos collègues ? L'UNSA Énergies Corse constitue sa liste pour les prochaines élections professionnelles. Formation assurée, temps de délégation et accompagnement par l'équipe régionale. Rejoignez-nous !$t$, $t$Élections$t$, $t$Corse$t$, true, '2026-11-07T04:00:00+01:00'),
($t$Égalité professionnelle : des avancées en Grand Est$t$, $t$La commission égalité, où siègent vos élus UNSA, a obtenu un budget dédié au rattrapage des écarts de rémunération et l'ouverture de postes techniques aux candidatures féminines à Strasbourg. Un suivi sera présenté chaque semestre.$t$, $t$Égalité H/F$t$, $t$Grand Est$t$, true, '2026-10-21T01:00:00+01:00'),
($t$Élections professionnelles : la liste UNSA Grand Est se construit$t$, $t$Vous souhaitez vous engager pour vos collègues ? L'UNSA Énergies Grand Est constitue sa liste pour les prochaines élections professionnelles. Formation assurée, temps de délégation et accompagnement par l'équipe régionale. Rejoignez-nous !$t$, $t$Élections$t$, $t$Grand Est$t$, true, '2026-10-10T02:00:00+01:00'),
($t$Réunion d'information retraite à Lille$t$, $t$Calcul de pension, rachat de trimestres, cumul emploi-retraite : l'UNSA Énergies Hauts-de-France organise une réunion d'information ouverte à tous à Lille. Un conseiller répondra à vos questions individuelles à l'issue de la présentation. Inscription conseillée via « Nous contacter ».$t$, $t$Retraite$t$, $t$Hauts-de-France$t$, true, '2026-09-04T05:00:00+01:00'),
($t$Télétravail : point d'étape en Hauts-de-France$t$, $t$Un an après la signature de l'accord télétravail, l'UNSA Énergies Hauts-de-France dresse le bilan : demandes acceptées, refus contestés, équipements fournis. Si votre demande a été refusée sans motif clair, contactez vos représentants : nous vous accompagnons.$t$, $t$Télétravail$t$, $t$Hauts-de-France$t$, true, '2026-10-28T03:00:00+01:00'),
($t$Réunion d'information retraite à Paris$t$, $t$Calcul de pension, rachat de trimestres, cumul emploi-retraite : l'UNSA Énergies Île-de-France organise une réunion d'information ouverte à tous à Paris. Un conseiller répondra à vos questions individuelles à l'issue de la présentation. Inscription conseillée via « Nous contacter ».$t$, $t$Retraite$t$, $t$Île-de-France$t$, true, '2026-09-29T01:00:00+01:00'),
($t$Astreintes : l'UNSA obtient une revalorisation en Île-de-France$t$, $t$Après plusieurs mois de négociation, la délégation UNSA Énergies Île-de-France a obtenu une revalorisation des indemnités d'astreinte et une meilleure prise en compte des temps de trajet pour les interventions de nuit. Le détail de l'accord est disponible dans l'espace adhérent.$t$, $t$Négociation$t$, $t$Île-de-France$t$, true, '2026-09-16T03:00:00+01:00'),
($t$Réunion d'information retraite à Rouen$t$, $t$Calcul de pension, rachat de trimestres, cumul emploi-retraite : l'UNSA Énergies Normandie organise une réunion d'information ouverte à tous à Rouen. Un conseiller répondra à vos questions individuelles à l'issue de la présentation. Inscription conseillée via « Nous contacter ».$t$, $t$Retraite$t$, $t$Normandie$t$, true, '2026-10-13T03:00:00+01:00'),
($t$Télétravail : point d'étape en Normandie$t$, $t$Un an après la signature de l'accord télétravail, l'UNSA Énergies Normandie dresse le bilan : demandes acceptées, refus contestés, équipements fournis. Si votre demande a été refusée sans motif clair, contactez vos représentants : nous vous accompagnons.$t$, $t$Télétravail$t$, $t$Normandie$t$, true, '2026-11-06T08:00:00+01:00'),
($t$Mobilité : vos droits en cas de réorganisation à Bordeaux$t$, $t$Le projet de réorganisation annoncé pour le site de Bordeaux soulève de nombreuses questions. L'UNSA Énergies Nouvelle-Aquitaine a demandé la communication du calendrier détaillé et la garantie d'un accompagnement individuel pour chaque salarié concerné.$t$, $t$Mobilité$t$, $t$Nouvelle-Aquitaine$t$, true, '2026-11-01T04:00:00+01:00'),
($t$Permanence syndicale à Limoges$t$, $t$Vos représentants UNSA Énergies Nouvelle-Aquitaine tiennent une permanence chaque premier mardi du mois, de 11h30 à 14h, sur le site de Limoges. Venez échanger sur vos droits, votre parcours professionnel ou toute difficulté rencontrée au travail. Sans rendez-vous et en toute confidentialité.$t$, $t$Permanence$t$, $t$Nouvelle-Aquitaine$t$, true, '2026-09-23T09:00:00+01:00'),
